def largest_smallest_integers(lst):
    negative = []
    positive = []

    for num in lst:
        if num < 0:
            if negative:
                negative[-1] = max(num, negative[-1])
            else:
                negative.append(num)
        elif num > 0:
            if positive:
                positive[0] = min(num, positive[0])
            else:
                positive.append(num)

    return (max(negative) if negative else None, min(positive) if positive else None)

